  region.Sequence.ShakeEnabled=false;yield return WalkRouteFrom(region,8,10);if(ended)yield break;yield return Capture("shake-disabled-stable-approach");Check("no shake offset persists when disabled",region.Presentation.VisualOffset==Vector2.zero);SporeSaveManager.FailNextDevelopmentWrite("validated");yield return WalkTo(region,region.Definition.Exit);yield return Wait(()=>Find<CampSceneController>()!=null&&Find<SettlementCampRegion>()!=null&&Find<SettlementCampRegion>().Ready&&Find<CampPlayableSpawner>()?.SpawnedPlayer!=null,"failed arrival reaches initialized Camp");if(ended)yield break;for(int i=0;i<3;i++)yield return null;Check("failed Intro commit retains pending arrival and beginning save",!Find<CampSceneController>().WorldInputReady&&CampArrivalContext.HasPending&&File.ReadAllText(SporeSaveManager.GetSlotPath(1))==initial&&SporeSaveManager.ShouldLoadIntro(SporeSaveManager.LoadSlot(1))&&!StoryEventService.IsCompleted(GameState.Instance,StoryEventIds.ASporeHatchesCampDiscovered));yield return Capture("failed-intro-arrival-held-safe");Find<CampSceneController>().RetryDevelopmentArrival();yield return Wait(CampReady,"authored Intro reaches real replacement Camp");if(ended)yield break;
