 }
 IEnumerator WalkRoute(IntroRegion r,int end)=>WalkRouteFrom(r,1,end);
 IEnumerator WalkRouteFrom(IntroRegion r,int start,int end){for(int i=start;i<=end&&!ended;i++){yield return WalkTo(r,r.Definition.Route[i]);if(ended)yield break;}}
 IEnumerator WalkTo(IntroRegion r,Point2 logical)
 {var goal=r.World(logical);float end=Time.realtimeSinceStartup+35;while(r!=null&&r.Player!=null&&!r.Sequence.Arriving&&Vector2.Distance(r.Player.transform.position,goal)>.21f&&Time.realtimeSinceStartup<end&&!ended){var delta=goal-(Vector2)r.Player.transform.position;var keys=new List<Key>();if(delta.x>.1f)keys.Add(Key.D);if(delta.x<-.1f)keys.Add(Key.A);if(delta.y>.1f)keys.Add(Key.W);if(delta.y<-.1f)keys.Add(Key.S);InputSystem.QueueStateEvent(keyboard,new KeyboardState(keys.ToArray()));yield return null;}InputSystem.QueueStateEvent(keyboard,new KeyboardState());if(r!=null&&!r.Sequence.Arriving&&Time.realtimeSinceStartup>=end){Check("walk reaches authored waypoint "+logical,false);Fail();}}
 IEnumerator DigPlug(IntroRegion r){yield return WalkTo(r,new Point2(97.5,47.5));float end=Time.realtimeSinceStartup+15;while(!ended&&r!=null&&!r.Sequence.PlugCleared&&Time.realtimeSinceStartup<end){var point=r.RegionCamera.WorldToScreenPoint(r.Render(r.World(new Point2(100.5,47.5))));InputSystem.QueueStateEvent(mouse,new MouseState{position=new Vector2(point.x,point.y)});InputSystem.QueueStateEvent(keyboard,new KeyboardState(Key.LeftShift,Key.D));yield return null;}InputSystem.QueueStateEvent(keyboard,new KeyboardState());Check("actual Shift digging breaches required dirt",r!=null&&r.Sequence.PlugCleared);if(r==null||!r.Sequence.PlugCleared)Fail();}
 IEnumerator DigAt(IntroRegion r,Point2 actor,Point2 target,float seconds){var body=r.Player.GetComponent<Rigidbody2D>();var p=r.World(actor);if(!TileMover.CanOccupyBox(r,p,TileMover.GetMapClearanceExtents(body,.22f))){Check("optional pocket approach has body clearance",false);Fail();yield break;}body.position=p;r.Player.transform.position=p;body.linearVelocity=Vector2.zero;Physics2D.SyncTransforms();float until=Time.realtimeSinceStartup+seconds;while(Time.realtimeSinceStartup<until&&!ended){var screen=r.RegionCamera.WorldToScreenPoint(r.Render(r.World(target)));InputSystem.QueueStateEvent(mouse,new MouseState{position=new Vector2(screen.x,screen.y)});var delta=r.World(target)-(Vector2)r.Player.transform.position;var keys=new List<Key>{Key.LeftShift};if(delta.magnitude>.35f){if(delta.x>.1f)keys.Add(Key.D);if(delta.x<-.1f)keys.Add(Key.A);if(delta.y>.1f)keys.Add(Key.W);if(delta.y<-.1f)keys.Add(Key.S);}InputSystem.QueueStateEvent(keyboard,new KeyboardState(keys.ToArray()));yield return null;}InputSystem.QueueStateEvent(keyboard,new KeyboardState());}
 IEnumerator Capture(string name){Stage61RuntimeMetrics.Mark("Intro / "+name);yield return new WaitForEndOfFrame();var image=ScreenCapture.CaptureScreenshotAsTexture();try{File.WriteAllBytes(Path.Combine(directory,name+".png"),image.EncodeToPNG());}finally{Destroy(image);}}
 void ExportGrid(IntroRegion r){using(var f=new StreamWriter(Path.Combine(directory,"intro-grid.csv"))){f.WriteLine("x,y,solid,permanent,plug,collapseMask,concealed");for(int y=0;y<80;y++)for(int x=0;x<160;x++)f.WriteLine(x+","+y+","+(r.State.World.IsSolid(x,y)?1:0)+","+(r.Definition.Protected(x,y)?1:0)+","+(r.Definition.IsPlug(x,y)?1:0)+","+(r.Definition.PlacementAllowed(x,y)?1:0)+","+(r.Definition.Concealed.Any(g=>g.Cells.Contains(y*160+x))?1:0));}}
 [Serializable]sealed class Result{public bool finished;public string error;public string[] checks,runtimeErrors;}
 void Fail(){if(ended)return;ended=true;File.WriteAllText(Path.Combine(directory,"result.json"),JsonUtility.ToJson(new Result{finished=true,error="Intro validation failed",checks=FinalChecks.ToArray(),runtimeErrors=errors.ToArray()},true));Application.Quit(1);}
 void OnDestroy(){Application.logMessageReceived-=Observe;if(keyboard!=null)InputSystem.RemoveDevice(keyboard);if(mouse!=null)InputSystem.RemoveDevice(mouse);}
